static int mtk_flow_offload_destroy ( struct mtk_eth * eth , struct flow_cls_offload * f ) { struct mtk_flow_entry * entry ; entry = rhashtable_lookup ( & eth -> flow_table , & f -> cookie , mtk_flow_ht_params ) ; if ( ! entry ) { return - ENOENT ; } mtk_foe_entry_clear ( eth -> ppe [ entry -> ppe_index ] , entry ) ; rhashtable_remove_fast ( & eth -> flow_table , & entry -> node , mtk_flow_ht_params ) ; kfree ( entry ) ; return 0 ; } 